 $('#add-course-area')?.addEventListener('click',()=>{const s=subject(state.activeSubject),name=prompt('Course area name');if(s&&name?.trim()){s.areas=s.areas||[];s.areas.push({id:crypto.randomUUID(),name:name.trim(),covered:false});save();render();}});$('#add-assessment-weight')?.addEventListener('click',()=>{const s=subject(state.activeSubject),name=prompt('Assessment component name');if(!s||!name?.trim())return;const weight=Number(prompt('Weight (%)','0'));if(weight<0||weight>100||!Number.isFinite(weight)){toast('Enter a percentage from 0 to 100.');return;}s.assessments=s.assessments||[];s.assessments.push({id:crypto.randomUUID(),name:name.trim(),weight});save();render();});$$('[data-delete-weight]').forEach(b=>b.onclick=()=>{const s=subject(state.activeSubject);s.assessments=s.assessments.filter(x=>x.id!==b.dataset.deleteWeight);save();render();});
