 $('#add-session')?.addEventListener('click',()=>{const title=prompt('Session title');if(!title?.trim())return;const date=prompt('Session date (YYYY-MM-DD)',dayKey());if(!date||Number.isNaN(new Date(date).getTime()))return;const subjectName=state.subjects.length?prompt('Subject name: '+state.subjects.map(s=>s.name).join(', '),state.subjects[0].name):'';const subjectId=state.subjects.find(s=>s.name===subjectName)?.id||'';state.sessions.push({id:crypto.randomUUID(),planned:true,completed:false,title:title.trim(),date,time:'',subject:subjectId||'',minutes:0,type:'planned'});save();render();});$$('[data-complete-session]').forEach(b=>b.onclick=()=>{const s=state.sessions.find(x=>x.id===b.dataset.completeSession);if(s){const raw=prompt('How many minutes did you study?','25');if(raw===null)return;const minutes=Number(raw);if(!Number.isFinite(minutes)||minutes<0||minutes>720){toast('Enter a duration from 0 to 720 minutes.');return;}s.minutes=minutes;s.completed=true;s.planned=false;save();render();}});$$('[data-delete-session]').forEach(b=>b.onclick=()=>{state.sessions=state.sessions.filter(s=>s.id!==b.dataset.deleteSession);save();render();});
