 $('#export-data')?.addEventListener('click',()=>{const a=document.createElement('a'),blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download=`studyloop-${dayKey()}.json`;a.click();URL.revokeObjectURL(a.href);});$('#import-data')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data||typeof data!=='object'||!Array.isArray(data.subjects)||!Array.isArray(data.cards))throw Error('This file is not a StudyLoop backup.');if(!confirm('Replace the study data in this browser with this backup?'))return;const restored={...JSON.parse(JSON.stringify(seed)),...data};for(const key of ['subjects','cards','decks','quizResults','quizDraft','mistakes','sessions','blurtings','maps','sacs'])if(!Array.isArray(restored[key]))restored[key]=[];for(const key of Object.keys(state))delete state[key];Object.assign(state,restored);cards.splice(0,...cards.length,...state.cards);state.cards=cards;save();render();toast('Backup restored.');}catch(err){toast(err.message||'Could not read that backup.');}finally{e.target.value='';}});$('#reset-data')?.addEventListener('click',()=>{if(!confirm('Clear all StudyLoop records saved in this browser?'))return;if(focusClock?.interval)clearInterval(focusClock.interval);for(const k of Object.keys(state))delete state[k];Object.assign(state,JSON.parse(JSON.stringify(seed)));cards.splice(0);state.cards=cards;save();render();toast('Study data reset.');});
