function bindTimer(){const start=$('#focus-start');if(!start)return;$('#focus-duration').onchange=e=>{state.focusMinutes=Math.max(1,Math.min(180,Number(e.target.value)||25));save();};$('#break-duration').onchange=e=>{state.breakMinutes=Math.max(1,Math.min(60,Number(e.target.value)||5));save();};start.onclick=()=>{if(!focusClock)focusClock={remaining:(state.focusMinutes||25)*60,phase:'focus',running:false};if(focusClock.running){focusClock.running=false;clearInterval(focusClock.interval);focusClock.interval=null;start.textContent='Resume';return;}focusClock.running=true;start.textContent='Pause';focusClock.interval=setInterval(()=>{focusClock.remaining--;const out=$('#focus-clock');if(out)out.textContent=`${String(Math.floor(focusClock.remaining/60)).padStart(2,'0')}:${String(focusClock.remaining%60).padStart(2,'0')}`;if(focusClock.remaining<=0){clearInterval(focusClock.interval);focusClock.interval=null;focusClock.running=false;if(focusClock.phase==='focus'){state.sessions.push({date:dayKey(),type:'Pomodoro',title:$('#focus-topic')?.value||'Focus session',subject:$('#focus-subject')?.value||'',minutes:state.focusMinutes||25,completed:true});save();toast('Focus block completed and logged. Take a break.');focusClock={remaining:(state.breakMinutes||5)*60,phase:'break',running:false};}else{toast('Break complete. Start another focus block when ready.');focusClock={remaining:(state.focusMinutes||25)*60,phase:'focus',running:false};}render();}},1000);};$('#focus-reset').onclick=()=>{if(focusClock?.interval)clearInterval(focusClock.interval);focusClock={remaining:(Number($('#focus-duration').value)||25)*60,phase:'focus',running:false};render();};}
function bindAiSettings(){if(!$('#ai-status'))return;fetch('/api/ai/status').then(r=>r.json()).then(x=>{$('#ai-status').textContent=x.configured?`Connected to ${x.provider} · ${x.model}. Key is held only in server memory.`:'No key connected. Add an Anthropic API key to enable AI tools.';}).catch(()=>{$('#ai-status').textContent='Start StudyLoop with the local server to connect AI.';});$('#save-ai-key')?.addEventListener('click',async()=>{const key=$('#ai-key').value.trim();if(!key){toast('Paste your API key first.');return;}try{const r=await fetch('/api/ai/config',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({key,model:$('#ai-model').value.trim()})});const x=await r.json();if(!r.ok)throw Error(x.error);$('#ai-key').value='';$('#ai-status').textContent=`Connected to ${x.provider} · ${x.model}. Key is held only in server memory.`;toast('AI key connected for this server session.');}catch(err){toast(err.message||'Could not connect the key.');}});$('#remove-ai-key')?.addEventListener('click',async()=>{await fetch('/api/ai/config',{method:'DELETE'}).catch(()=>{});$('#ai-status').textContent='AI key removed from server memory.';toast('AI key removed.');});}
function bindAiPage(){let selected=$('.ai-tool.selected')?.dataset.aiTool||aiTools[0];$$('[data-ai-tool]').forEach(b=>b.addEventListener('click',()=>{$$('.ai-tool').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=b.dataset.aiTool;$('#chat-title').textContent=selected;}));$('#send-ai')?.addEventListener('click',async()=>{const box=$('#ai-prompt'),prompt=box.value.trim();if(!prompt)return;state.aiMessages.push({role:'user',text:prompt});box.value='';render();const area=$('#chat-messages');if(area)area.innerHTML+='<div class="chat-bubble assistant">Thinking…</div>';try{const r=await fetch('/api/ai/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt,tool:selected,subject:$('#ai-subject').value})});const x=await r.json();if(!r.ok)throw Error(x.error);state.aiMessages.push({role:'assistant',text:x.answer});}catch(e){state.aiMessages.push({role:'assistant',text:e.message+' Go to Settings to connect your key.'});}save();render();});$('#clear-chat')?.addEventListener('click',()=>{state.aiMessages=[];render();});}
function bindQuizzes(){$$('[data-generate]').forEach(b=>b.addEventListener('click',async()=>{const notes=$('#quiz-notes').value.trim();if(!notes){toast('Add your notes first.');return;}b.disabled=true;b.textContent='Preparing…';try{const r=await fetch('/api/ai/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:b.dataset.generate,notes,subject:$('#quiz-subject').value,topic:$('#quiz-topic').value})});const x=await r.json();if(!r.ok)throw Error(x.error);const items=JSON.parse(x.answer);state.decks.push({kind:b.dataset.generate,title:$('#quiz-topic').value||$('#quiz-subject').value,items});save();render();toast('Your set is ready.');}catch(e){toast(e.message);}finally{b.disabled=false;}}));$$('[data-deck]').forEach(b=>b.addEventListener('click',()=>{const d=state.decks[Number(b.dataset.deck)];$('#deck-content').innerHTML=`<section class="panel generated-deck"><div class="panel-title"><h3>${escapeHtml(d.title)}</h3><button class="text-link" id="close-deck">Close</button></div>${d.items.map((x,i)=>`<details><summary>${i+1}. ${escapeHtml(x.question||x.topic||'Topic')}</summary><p>${escapeHtml(x.answer||JSON.stringify(x.children||[]))}</p>${x.hint?`<small>Hint: ${escapeHtml(x.hint)}</small>`:''}</details>`).join('')}</section>`;$('#close-deck').onclick=()=>$('#deck-content').replaceChildren();}));}
