// User-owned data views. Empty states stay empty until the learner records real material/activity.
function subjectPage(){const s=subject(state.activeSubject);if(!s)return `${pageHeading('SUBJECTS','Choose a subject.','Add your actual subjects and course details to organize study records.')}<button class="primary-button" data-add-subject>Add subject</button>`;const areas=s.areas||[];return `${pageHeading('SUBJECT HUB',s.name,s.course||'Add your course or curriculum details.')}
<div class="subject-hub-grid"><section class="panel subject-score"><div class="panel-title"><h3>Target study score</h3><span>Your chosen target, not a prediction</span></div><div class="score-number" id="score-value">${s.target??'—'}</div><input id="target-score" type="range" min="10" max="50" step="1" value="${s.target??'—'}"><div class="range-labels"><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span></div></section><section class="panel"><div class="panel-title"><h3>Recorded for this subject</h3><button class="text-link" id="edit-subject">Edit</button></div><p>${state.cards.filter(c=>c.subject===s.id).length} cards · ${state.sessions.filter(x=>x.subject===s.id&&x.completed).reduce((n,x)=>n+(Number(x.minutes)||0),0)} minutes · ${state.decks.filter(q=>q.subject===s.id).length} quizzes.</p></section></div>
<section class="panel course-panel"><div class="panel-title"><div><h3>Course areas</h3><small>Add your own curriculum areas and mark them as you cover them.</small></div><button class="text-link" id="add-course-area">+ Add area</button></div>${areas.length?areas.map((a,i)=>`<label class="course-row"><span>${escapeHtml(a.name)}</span><input type="checkbox" data-course="${a.id}" ${a.covered?'checked':''}></label>`).join(''):'<div class="empty-state">No course areas entered yet.</div>'}</section><section class="panel"><div class="panel-title"><h3>Assessment weighting</h3><button class="text-link" id="add-assessment-weight">+ Add component</button></div>${s.assessments?.length?s.assessments.map(a=>`<div class="assessment-row"><span>${escapeHtml(a.name)}</span><strong>${a.weight}%</strong><i style="--weight:${a.weight}%"></i><button class="text-link" data-delete-weight="${a.id}">Remove</button></div>`).join(''):'<p class="subtle">No assessment weights recorded. Add the official components for your course if useful.</p>'}</section>`;}
function progress(){const done=state.sessions.filter(s=>s.completed),mins=done.reduce((n,s)=>n+(Number(s.minutes)||0),0),avg=state.quizResults.length?Math.round(state.quizResults.reduce((n,r)=>n+r.score/Math.max(1,r.total),0)/state.quizResults.length*100):null;const days=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(13-i));const k=dayKey(d);return {k,m:done.filter(s=>s.date===k).reduce((n,s)=>n+(Number(s.minutes)||0),0)};});const max=Math.max(1,...days.map(d=>d.m));return `${pageHeading('PROGRESS','Your recorded progress.','Every number here comes from activity and results you have saved.','LAST 14 DAYS')}<div class="progress-overview"><section class="metric-card"><div class="metric-label">Completed sessions</div><div class="metric-value">${done.length}</div><div class="metric-foot">${mins} recorded minutes</div></section><section class="metric-card"><div class="metric-label">Quiz average</div><div class="metric-value">${avg===null?'—':avg+'%'}</div><div class="metric-foot">${state.quizResults.length} self-marked attempts</div></section><section class="metric-card"><div class="metric-label">Current streak</div><div class="metric-value">${getStreak()} days</div><div class="metric-foot">Based on completed study days</div></section></div><section class="panel chart-card"><div class="panel-title"><h3>Study time · minutes per day</h3></div><div class="bar-chart">${days.map(d=>`<div class="bar-col"><div class="bar ${d.k===dayKey()?'today':''}" style="height:${Math.max(2,d.m/max*100)}%" title="${d.m} min"></div>${new Date(d.k+'T12:00:00').getDate()}</div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h3>Session history</h3></div>${done.length?done.slice().reverse().map(s=>`<div class="review-row"><span class="subject-icon">${escapeHtml(s.type?.slice(0,2)||'ST')}</span><div class="review-info"><strong>${escapeHtml(s.title)}</strong><small>${s.date} · ${s.minutes} min · ${escapeHtml(subject(s.subject)?.name||'No subject')}</small></div></div>`).join(''):'<div class="empty-state">No completed sessions yet.</div>'}</section>`;}
function settings(){return `${pageHeading('YOUR PROFILE','Your profile and local data.','Set your actual course details. Progress is stored only in this browser.')}
<section class="panel settings-card"><div class="panel-title"><h3>Study profile</h3></div><div class="setting-row"><div><strong>Name</strong><small>Optional profile label</small></div><input id="name-setting" value="${escapeHtml(state.name)}" placeholder="Your name"></div><div class="setting-row"><div><strong>Year level</strong><small>Used to label your study space</small></div><input id="year-setting" value="${escapeHtml(state.year)}" placeholder="e.g. Year 12"></div><div class="setting-row"><div><strong>Course / curriculum</strong><small>Optional</small></div><input id="course-setting" value="${escapeHtml(state.course||'')}" placeholder="e.g. VCE"></div><div class="setting-row"><div><strong>AI provider key</strong><small id="ai-status">Optional. The local server holds your key in memory.</small></div><div class="ai-key-controls"><input id="ai-key" type="password" autocomplete="off" placeholder="API key"><input id="ai-model" value="claude-sonnet-4-6" aria-label="Model"><button class="secondary-button" id="save-ai-key">Connect</button><button class="text-link" id="remove-ai-key">Remove</button></div></div><div class="setting-row"><div><strong>Export data</strong><small>Save a JSON backup of your local study records.</small></div><button class="secondary-button" id="export-data">Export</button></div><div class="setting-row"><div><strong>Import data</strong><small>Restore a StudyLoop JSON backup.</small></div><input id="import-data" type="file" accept="application/json"></div><div class="setting-row"><div><strong>Reset progress</strong><small>Remove stored study records from this browser.</small></div><button class="text-link" id="reset-data">Reset data</button></div></section>`;}
function mindmaps(){const m=state.maps.find(x=>x.id===state.activeMap);return `${pageHeading('MIND MAPS','Build your own topic maps.','Create the root and branches yourself. Nothing is generated automatically.')}
<section class="panel"><form id="map-form"><label class="field-label">Map title<input id="map-title" name="title" required maxlength="120" placeholder="Topic or course area"></label><label class="field-label">Subject<select name="subject"><option value="">No subject</option>${state.subjects.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('')}</select></label><button class="primary-button">Create map</button></form></section><section class="panel"><div class="panel-title"><h3>Your maps</h3></div>${state.maps.length?state.maps.map(x=>`<button class="map-chip" data-open-map="${x.id}">${escapeHtml(x.title)}</button>`).join(''):'<div class="empty-state">No maps created yet.</div>'}${m?`<div class="map-root">${escapeHtml(m.title)}</div><form id="branch-form" class="inline-form"><input name="text" required maxlength="120" placeholder="Add a branch"><select name="parent"><option value="">Under root</option>${m.nodes.map(n=>`<option value="${n.id}">${escapeHtml(n.text)}</option>`).join('')}</select><button class="secondary-button">Add branch</button></form><div class="map-tree">${m.nodes.map(n=>`<div class="map-branch" style="margin-left:${n.parent?24:0}px">${escapeHtml(n.text)} <button class="text-link" data-delete-branch="${n.id}">Remove</button></div>`).join('')}</div><button class="text-link" data-delete-map="${m.id}">Delete map</button>`:''}</section>`;}
function revision(){const queue=[...dueCards().map(c=>({id:c.id,text:c.prompt,type:'card'})),...dueMistakes().map(m=>({id:m.id,text:m.prompt,type:'mistake'}))];return `${pageHeading('REVISION MODE','Review due work.','This queue includes due flashcards and questions you marked as missed.')}
<section class="panel"><div class="panel-title"><h3>Current review queue</h3><span>${queue.length} items</span></div>${queue.length?queue.map(x=>`<div class="review-row"><span class="subject-icon">${x.type==='card'?'FC':'!'}</span><div class="review-info"><strong>${escapeHtml(x.text)}</strong><small>${x.type==='card'?'Flashcard':'Missed quiz question'}</small></div><button class="text-link" ${x.type==='card'?`data-review-card="${x.id}"`:`data-review-mistake="${state.mistakes.findIndex(m=>m.id===x.id)}"`}>Review</button></div>`).join(''):'<div class="empty-state">No review items due. Create cards or complete quizzes to build this queue.</div>'}</section>`;}
function quizzes(){const run=state.quizRun&&state.decks.find(q=>q.id===state.quizRun.deckId);return `${pageHeading('QUIZZES','Your cards and quizzes.','Create questions from your own course material and self-mark each attempt.')}
<div class="tool-grid"><section class="panel"><div class="panel-title"><h3>New flashcard</h3></div><form id="new-card-form"><label class="field-label">Subject<select name="subject"><option value="">No subject</option>${state.subjects.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('')}</select></label><label class="field-label">Topic<input name="topic" placeholder="Optional topic"></label><label class="field-label">Question<input name="prompt" required maxlength="500" placeholder="A question you can answer from memory"></label><label class="field-label">Answer<textarea name="answer" required placeholder="The explanation or key points"></textarea></label><button class="primary-button">Save flashcard</button></form></section><section class="panel"><div class="panel-title"><h3>Build a quiz</h3></div><form id="new-quiz-form"><label class="field-label">Quiz title<input id="draft-title" required value="${escapeHtml(state.quizDraftTitle||'')}" placeholder="Name this quiz"></label><label class="field-label">Subject<select id="draft-subject"><option value="">No subject</option>${state.subjects.map(s=>`<option value="${s.id}" ${state.quizDraftSubject===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label><label class="field-label">Question<input id="draft-prompt" maxlength="500" placeholder="Write a quiz question"></label><label class="field-label">Model answer<textarea id="draft-answer" placeholder="Add key points"></textarea></label><div class="button-row"><button class="secondary-button" type="button" id="add-question">Add question</button><button class="primary-button">Save quiz (${state.quizDraft.length})</button></div></form>${state.quizDraft.map((q,i)=>`<div class="topic-row">${i+1}. ${escapeHtml(q.question)} <button class="text-link" data-remove-draft="${i}">Remove</button></div>`).join('')}</section></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>Saved quizzes</h3><span>${state.decks.length}</span></div>${state.decks.length?state.decks.map(q=>`<div class="review-row"><span class="subject-icon">Q</span><div class="review-info"><strong>${escapeHtml(q.title)}</strong><small>${q.items.length} questions · ${escapeHtml(subject(q.subject)?.name||'No subject')}</small></div><button class="text-link" data-take-quiz="${q.id}">Take quiz</button></div>`).join(''):'<div class="empty-state">No quizzes yet. Add your own questions and answers to build one.</div>'}</section><section class="panel"><div class="panel-title"><h3>Mistake bank</h3><span>${state.mistakes.filter(m=>!m.mastered).length} open</span></div>${state.mistakes.map((m)=>({m,i:state.mistakes.indexOf(m)})).filter(x=>!x.m.mastered).map(({m,i})=>`<div class="review-row"><div class="review-info"><strong>${escapeHtml(m.prompt)}</strong><small>${escapeHtml(m.source||'Quiz')} · due ${m.due||'today'}</small></div><button class="text-link" data-review-mistake="${i}">Review</button></div>`).join('')||'<div class="empty-state">No missed questions saved yet.</div>'}</section></div>
<section class="panel"><div class="panel-title"><h3>Flashcards</h3><span>${state.cards.length} saved</span></div>${state.cards.map(c=>`<div class="review-row">${subjectIcon(subject(c.subject))}<div class="review-info"><strong>${escapeHtml(c.prompt)}</strong><small>${escapeHtml(c.topic||'No topic')} · due ${c.due||'today'}</small></div></div>`).join('')||'<div class="empty-state">No cards yet. Create a flashcard to start a review schedule.</div>'}</section>${run?quizPlayer(run):''}`;}


function go(page){state.page=page;save();render();window.scrollTo({top:0,behavior:'smooth'});$('#sidebar').classList.remove('open');}
$$('.nav-item').forEach(el=>el.addEventListener('click',()=>go(el.dataset.page)));
$$('.profile-button,.small-avatar').forEach(el=>el.addEventListener('click',()=>go('settings')));
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
 document.addEventListener('click',e=>{const item=e.target.closest('[data-subject]');if(item){state.activeSubject=item.dataset.subject;go('subject');}});
function openSubjectModal(existing=undefined){const overlay=document.createElement('div');overlay.className='subject-modal-backdrop';overlay.innerHTML=`<section class="subject-modal" role="dialog" aria-modal="true" aria-label="${existing?'Edit':'Add'} subject"><h3>${existing?'Edit':'Add'} subject</h3><form id="subject-form"><label class="field-label">Subject name<input name="name" required maxlength="80" value="${escapeHtml(existing?.name||'')}" placeholder="Your subject"></label><label class="field-label">Course / level<input name="course" maxlength="100" value="${escapeHtml(existing?.course||'')}" placeholder="Optional course details"></label><div class="modal-actions"><button class="secondary-button" type="button" data-cancel>Cancel</button><button class="primary-button">Save subject</button>${existing?'<button class="text-link" type="button" data-delete-subject>Delete</button>':''}</div></form></section>`;document.body.append(overlay);overlay.querySelector('[data-cancel]').onclick=()=>overlay.remove();overlay.querySelector('#subject-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim(),course=String(f.get('course')).trim();if(existing){existing.name=name;existing.course=course;}else{const colors=['#607b9a','#668a69','#987568','#527b86','#765f97'];const tone=colors[state.subjects.length%colors.length],id=crypto.randomUUID();state.subjects.push({id,name,course,short:name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),tone,bg:'#f0f1ec',areas:[],assessments:[],target:null});state.activeSubject=id;}save();overlay.remove();render();toast('Subject saved.');};overlay.querySelector('[data-delete-subject]')?.addEventListener('click',()=>{if(!confirm('Delete this subject? Its study records will be unassigned.'))return;for(const list of [state.cards,state.decks,state.sessions,state.sacs])for(const x of list)if(x.subject===existing.id)x.subject='';state.subjects=state.subjects.filter(s=>s.id!==existing.id);state.activeSubject='';save();overlay.remove();render();});}
render();
